CREATE OR REPLACE FUNCTION public.guard_jls_certified_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sid uuid;begin
 if tg_op='INSERT' then
  sid=new.run_id;
  perform pg_advisory_xact_lock_shared(hashtextextended('jls-frozen-source:'||sid::text,0));
  if exists(select 1 from public.analysis_jls_source_certificate_refs where source_table='analysis_jls_restaurant_runs' and source_id=sid)
  then raise exception 'JLS_CERTIFIED_SOURCE_IMMUTABLE';end if;
  return new;
 end if;
 if tg_table_name='historical_report_runs' and tg_op='UPDATE'
 and exists(select 1 from public.report_generation_requests q where q.source_run_id=old.id and q.engine='jev_sol_v2')
 and (to_jsonb(new)-array['status','locked_by','lease_until','updated_at','completed_at','error_code','last_error'])=(to_jsonb(old)-array['status','locked_by','lease_until','updated_at','completed_at','error_code','last_error']) then return new;end if; if exists(select 1 from public.analysis_jls_source_certificate_refs where source_table=tg_table_name and source_id=old.id)
 then raise exception 'JLS_CERTIFIED_SOURCE_IMMUTABLE';end if;
 if tg_op='DELETE' then return old;end if;return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_parallel_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 if tg_op='DELETE' then raise exception 'IMMUTABLE_HISTORY';end if;
 if old.derived_report is not null or old.raw_response is not null or old.imported_derivative_id is not null then raise exception 'IMMUTABLE_HISTORY';end if;
 if (to_jsonb(new)-array['state','error_code','raw_response','original_report','derived_report','corrections','controls','statistics','usage','generated_at'])<>(to_jsonb(old)-array['state','error_code','raw_response','original_report','derived_report','corrections','controls','statistics','usage','generated_at']) then raise exception 'IMMUTABLE_SOURCE';end if;return new;
end $function$

CREATE OR REPLACE FUNCTION public.historical_v10_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare state text;
begin
 if tg_table_name='historical_report_runs' then
  if old.snapshot->>'analysis_version' is distinct from '10' then if tg_op='DELETE' then return old;end if;return new;end if;
  if old.status='completed' then raise exception 'REPORT_V10_IMMUTABLE';end if;
  if tg_op='UPDATE' and (old.snapshot-'publication') is distinct from (new.snapshot-'publication') then raise exception 'REPORT_V10_SOURCE_IMMUTABLE';end if;
 else
  select status into state from public.historical_report_runs where id=case when tg_op='DELETE' then old.run_id else new.run_id end for update;
  if state='completed' then raise exception 'REPORT_V10_IMMUTABLE';end if;
  if tg_op='UPDATE' and (to_jsonb(old)-array['served_models','jev_theme_requests','jev_sentiment_requests','jev_input_tokens','jev_output_tokens','jev_retry_count','jev_elapsed_ms','sol_narrative_calls','sol_narrative_input_tokens','sol_narrative_output_tokens','sol_narrative_elapsed_ms','narrative_state','narrative_error','narrative_result','usage_complete']) is distinct from (to_jsonb(new)-array['served_models','jev_theme_requests','jev_sentiment_requests','jev_input_tokens','jev_output_tokens','jev_retry_count','jev_elapsed_ms','sol_narrative_calls','sol_narrative_input_tokens','sol_narrative_output_tokens','sol_narrative_elapsed_ms','narrative_state','narrative_error','narrative_result','usage_complete']) then raise exception 'REPORT_V10_CONFIG_IMMUTABLE';end if;
 end if;
 if tg_op='DELETE' then return old;end if;return new;
end $function$

